enum FileErr: Error { case missing }
actor Storage {
    func read() async throws -> String { throw FileErr.missing }
}
let s = Storage()
do {
    _ = try await s.read()
} catch {
    print("Caught")
}

let t = Task {
    try Task.checkCancellation()
    return "Done"
}
t.cancel()
do {
    _ = try await t.value
} catch is CancellationError {
    print("Cancelled")
} catch {
    print("Other")
}

func sumNumbers(_ numbers: [Int]) async -> Int {
    var sum = 0
    for n in numbers { sum += n }
    return sum
}
print(await sumNumbers([1, 2, 3]))

actor BankAccount {
